mapper.select:
SELECT r.id AS id, r.refund_no AS refund_no, r.order_id AS order_id, r.type AS type, r.status AS status, r.amount AS amount, r.reason AS reason, r.remark AS remark, r.tracking_no AS tracking_no, r.applied_at AS applied_at, r.audited_at AS audited_at, r.shipped_at AS shipped_at, r.received_at AS received_at, r.refunded_at AS refunded_at, r.created_at AS created_at, o.order_no AS order_no, COALESCE(u.nickname, '用户****') AS user_nickname FROM refunds r LEFT JOIN orders o ON o.id = r.order_id LEFT JOIN users u ON u.id = r.user_id
AND r.status = #{status}
AND r.user_id = #{userId}
ORDER BY r.id DESC

mapper.update:
UPDATE refunds
   SET status     = 'CANCELLED',
       updated_at = CURRENT_TIMESTAMP
 WHERE id = #{refundId}
   AND user_id = #{userId}
   AND status = 'APPLIED'
